        {
            markerStart = -1;
            if (text == null || caret <= 0 || caret > text.Length) return false;

            char c = text[caret - 1];
            if (c != '-' && c != '*') return false;

            int lineStart = LineStart(text, caret - 1);
            if (!IsIndentation(text, lineStart, caret - 1)) return false;

            markerStart = caret - 1;
            return true;
